/**
 * Email Incident/Task Creation Flow
 *
 * This flow triggers when an email is received with "raise incident or task" in the subject:
 *
 * If email is from internal sender (ServiceNow) AND subject contains "P1":
 * - Create 2 P1 incident tasks:
 *   1. Task assigned to sender's manager with short description = email body
 *   2. Task assigned to sender with short description = email subject
 *
 * Otherwise:
 * - Create a P3 incident with email information
 *
 * Triggers on inbound email with specific subject pattern
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const emailIncidentTaskFlow = Flow(
    {
        $id: Now.ID['email_incident_task_flow'],
        name: 'Email Incident/Task Creation Flow',
        description: 'Creates incidents or tasks based on email content with "raise incident or task" in subject',
    },
    wfa.trigger(
        trigger.application.inboundEmail,
        { $id: Now.ID['inbound_email_trigger'] },
        {
            email_conditions: 'subjectLIKEraise incident or task',
            target_table: 'incident',
            order: 100,
            stop_condition_evaluation: false,
        }
    ),
    (params) => {
        // Log email received
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_email_received'],
                annotation: 'Log inbound email received',
            },
            {
                log_level: 'info',
                log_message: `Email received from: ${wfa.dataPill(params.trigger.from_address, 'string')}, Subject: ${wfa.dataPill(params.trigger.subject, 'string')}`,
            }
        )

        // Look up sender by email address
        const sender = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup_sender'],
                annotation: 'Retrieve sender user record',
            },
            {
                table: 'sys_user',
                conditions: `email=${wfa.dataPill(params.trigger.from_address, 'string')}`,
            }
        )

        // Check if sender is internal (from ServiceNow) AND subject contains P1
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(sender.Record.email, 'string')}LIKEservicenow^${wfa.dataPill(params.trigger.subject, 'string')}LIKEP1`,
                annotation: 'Check if internal sender and P1 request',
                $id: Now.ID['check_internal_p1'],
            },
            () => {
                // Log P1 internal request detected
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_p1_internal'],
                        annotation: 'Log P1 internal request detected',
                    },
                    {
                        log_level: 'warn',
                        log_message: `P1 request from internal sender detected: ${wfa.dataPill(sender.Record.name, 'string')}`,
                    }
                )

                // Look up sender's manager
                const senderManager = wfa.action(
                    action.core.lookUpRecord,
                    {
                        $id: Now.ID['lookup_sender_manager'],
                        annotation: 'Retrieve sender manager details',
                    },
                    {
                        table: 'sys_user',
                        conditions: `sys_id=${wfa.dataPill(sender.Record.manager, 'reference')}`,
                    }
                )

                // Create first P1 task - assigned to sender's manager with short description = email body
                const managerTask = wfa.action(
                    action.core.createTask,
                    {
                        $id: Now.ID['create_manager_task'],
                        annotation: 'Create P1 task for sender manager',
                    },
                    {
                        task_table: 'incident',
                        field_values: TemplateValue({
                            priority: 1,
                            assigned_to: wfa.dataPill(senderManager.Record.sys_id, 'reference'),
                            short_description: wfa.dataPill(params.trigger.inbound_email.body, 'string'),
                            description: `Email from: ${wfa.dataPill(params.trigger.from_address, 'string')}
Subject: ${wfa.dataPill(params.trigger.subject, 'string')}

${wfa.dataPill(params.trigger.inbound_email.body, 'string')}`,
                            urgency: 1,
                            impact: 1,
                            caller_id: wfa.dataPill(sender.Record.sys_id, 'reference'),
                        }),
                    }
                )

                // Log manager task created
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_manager_task_created'],
                        annotation: 'Log P1 task created for manager',
                    },
                    {
                        log_level: 'info',
                        log_message: `P1 task created for manager ${wfa.dataPill(senderManager.Record.name, 'string')}: ${wfa.dataPill(managerTask.Record, 'reference')}`,
                    }
                )

                // Create second P1 task - assigned to sender with short description = email subject
                const senderTask = wfa.action(
                    action.core.createTask,
                    {
                        $id: Now.ID['create_sender_task'],
                        annotation: 'Create P1 task for sender',
                    },
                    {
                        task_table: 'incident',
                        field_values: TemplateValue({
                            priority: 1,
                            assigned_to: wfa.dataPill(sender.Record.sys_id, 'reference'),
                            short_description: wfa.dataPill(params.trigger.subject, 'string'),
                            description: `Email from: ${wfa.dataPill(params.trigger.from_address, 'string')}
Subject: ${wfa.dataPill(params.trigger.subject, 'string')}

${wfa.dataPill(params.trigger.inbound_email.body, 'string')}`,
                            urgency: 1,
                            impact: 1,
                            caller_id: wfa.dataPill(sender.Record.sys_id, 'reference'),
                        }),
                    }
                )

                // Log sender task created
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_sender_task_created'],
                        annotation: 'Log P1 task created for sender',
                    },
                    {
                        log_level: 'info',
                        log_message: `P1 task created for sender ${wfa.dataPill(sender.Record.name, 'string')}: ${wfa.dataPill(senderTask.Record, 'reference')}`,
                    }
                )

                // Send confirmation notification to sender
                wfa.action(
                    action.core.sendNotification,
                    {
                        $id: Now.ID['send_p1_confirmation'],
                        annotation: 'Send P1 task creation confirmation',
                    },
                    {
                        table_name: 'incident',
                        record: wfa.dataPill(managerTask.Record, 'reference'),
                        notification: 'p1_tasks_created_notification',
                    }
                )

                // Log confirmation email sent
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_p1_confirmation_sent'],
                        annotation: 'Log P1 confirmation email sent',
                    },
                    {
                        log_level: 'info',
                        log_message: `P1 confirmation email sent to ${wfa.dataPill(params.trigger.from_address, 'string')}`,
                    }
                )
            }
        )

        // Else - create P3 incident
        wfa.flowLogic.else(
            {
                annotation: 'Create P3 incident for non-P1 or external requests',
                $id: Now.ID['create_p3_incident'],
            },
            () => {
                // Log P3 incident creation
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_p3_creation'],
                        annotation: 'Log P3 incident creation initiated',
                    },
                    {
                        log_level: 'info',
                        log_message: `Creating P3 incident from email: ${wfa.dataPill(params.trigger.subject, 'string')}`,
                    }
                )

                // Create P3 incident with email information
                const p3Incident = wfa.action(
                    action.core.createRecord,
                    {
                        $id: Now.ID['create_p3_incident_record'],
                        annotation: 'Create P3 incident from email',
                    },
                    {
                        table_name: 'incident',
                        values: TemplateValue({
                            priority: 4,
                            short_description: wfa.dataPill(params.trigger.subject, 'string'),
                            description: `Email from: ${wfa.dataPill(params.trigger.from_address, 'string')}
Subject: ${wfa.dataPill(params.trigger.subject, 'string')}

Email Body:
${wfa.dataPill(params.trigger.inbound_email.body, 'string')}`,
                            urgency: 3,
                            impact: 3,
                            caller_id: wfa.dataPill(sender.Record.sys_id, 'reference'),
                            contact_type: 'email',
                        }),
                    }
                )

                // Copy email attachments to the incident
                const emailAttachments = wfa.action(
                    action.core.getAttachmentsOnRecord,
                    {
                        $id: Now.ID['get_email_attachments'],
                        annotation: 'Retrieve email attachments',
                    },
                    {
                        source_record: `${wfa.dataPill(params.trigger.inbound_email.sys_id, 'reference')}`,
                    }
                )

                // Log attachment count
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_attachment_count'],
                        annotation: 'Log number of attachments found',
                    },
                    {
                        log_level: 'info',
                        log_message: `Found ${wfa.dataPill(emailAttachments.parameter1, 'integer')} attachments on email`,
                    }
                )

                // Loop through attachments and copy them to the incident
                wfa.flowLogic.forEach(
                    wfa.dataPill(emailAttachments.parameter, 'records'),
                    {
                        $id: Now.ID['foreach_copy_attachments'],
                        annotation: 'Copy each attachment to incident',
                    },
                    () => {
                        wfa.action(
                            action.core.copyAttachment,
                            {
                                $id: Now.ID['copy_attachment_to_incident'],
                                annotation: 'Copy attachment from email to incident',
                            },
                            {
                                table: 'incident',
                                target_record: wfa.dataPill(p3Incident.record, 'reference'),
                                attachment_record: wfa.dataPill(emailAttachments.parameter, 'records'),
                            }
                        )
                    }
                )

                // Log P3 incident created
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_p3_incident_created'],
                        annotation: 'Log P3 incident created successfully',
                    },
                    {
                        log_level: 'info',
                        log_message: `P3 incident created: ${wfa.dataPill(p3Incident.record, 'reference')} from email: ${wfa.dataPill(params.trigger.from_address, 'string')}`,
                    }
                )

                // Send confirmation email to sender
                wfa.action(
                    action.core.sendEmail,
                    {
                        $id: Now.ID['send_p3_confirmation'],
                        annotation: 'Send P3 incident creation confirmation',
                    },
                    {
                        ah_to: wfa.dataPill(params.trigger.from_address, 'string'),
                        ah_subject: `Incident Created: ${wfa.dataPill(params.trigger.subject, 'string')}`,
                        ah_body: `Dear sdfghj,

Your request has been received and an incident has been created:

Incident Number:345678
Priority: P3
Status: New

Our support team will review your incident and respond accordingly.

Best regards,
IT Support System`,
                        record: wfa.dataPill(p3Incident.record, 'reference'),
                        table_name: 'incident',
                    }
                )

                // Log confirmation email sent
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_p3_confirmation_sent'],
                        annotation: 'Log P3 confirmation email sent',
                    },
                    {
                        log_level: 'info',
                        log_message: `P3 confirmation email sent to ${wfa.dataPill(params.trigger.from_address, 'string')}`,
                    }
                )
            }
        )

        // Final log of email processing completion
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_email_processing_complete'],
                annotation: 'Log email processing completion',
            },
            {
                log_level: 'info',
                log_message: `Email processing completed for: ${wfa.dataPill(params.trigger.subject, 'string')}`,
            }
        )
    }
)
